mapper.select:
select t1.id, t1.job_name, t1.job_group, t1.cron, t1.job_type, t1.status, t1.schedule_type, COALESCE(SUM(CASE WHEN t2.status = '2' THEN 1 ELSE 0 END), 0) AS successNum, COALESCE(SUM(CASE WHEN t2.status = '3' THEN 1 ELSE 0 END), 0) AS failNum, COALESCE(SUM(CASE WHEN t2.status = '1' THEN 1 ELSE 0 END), 0) AS executingNum from sys_schedule_job t1 left join sys_schedule_record t2 on t1.id = t2.job_id and t2.del_flag = '0' where t1.del_flag = '0'
and t1.job_name like #{keyword}
and t1.status = #{request.status}
group by t1.id, t1.job_name, t1.job_group, t1.cron, t1.job_type, t1.status, t1.schedule_type
